import sys
import xml.etree.ElementTree as ET

def parse_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    clients = {}
    for client_elem in root.findall('client'):
        token = client_elem.get('token')
        jobs = set(client_elem.get('jobs').split(','))
        limit = int(client_elem.get('limit'))
        clients[token] = {'jobs': jobs, 'limit': limit, 'count': 0}
    return clients

def main():
    if len(sys.argv) != 2:
        sys.exit(0)
    config = parse_config(sys.argv[1])
    token_counts = {}

    for line in sys.stdin:
        parts = line.strip().split()
        if len(parts) != 2:
            continue
        token, job_name = parts
        if token not in config:
            print("UNKNOWN_TOKEN")
            continue
        client_data = config[token]
        if job_name not in client_data['jobs']:
            print("JOB_NOT_ALLOWED")
            continue
        if token_counts.get(token, 0) >= client_data['limit']:
            print("LIMIT_EXCEEDED")
        else:
            print("OK")
            token_counts[token] = token_counts.get(token, 0) + 1

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET

class Client:
    def __init__(self, token, jobs, limit):
        self.token = token
        self.jobs = set(jobs.split(','))
        self.limit = limit
        self.ok_count = 0

def load_clients(config_file):
    tree = ET.parse(config_file)
    root = tree.getroot()
    clients = {}
    for client_elem in root.findall('client'):
        token = client_elem.get('token')
        jobs = client_elem.get('jobs')
        limit = int(client_elem.get('limit'))
        clients[token] = Client(token, jobs, limit)
    return clients

def process_requests(clients):
    for line in sys.stdin:
        token, job_name = line.strip().split()
        if token not in clients:
            print('UNKNOWN_TOKEN')
            continue
        client = clients[token]
        if job_name not in client.jobs:
            print('JOB_NOT_ALLOWED')
            continue
        if client.ok_count >= client.limit:
            print('LIMIT_EXCEEDED')
        else:
            print('OK')
            client.ok_count += 1

if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(1)
    config_file = sys.argv[1]
    clients = load_clients(config_file)
    process_requests(clients)
